  'impostazioni.sdi.title': 'SDI-Vermittler-API',
  'impostazioni.sdi.intro': 'Konfigurieren Sie die API des Vermittlers für den Versand von E-Rechnungen an das Austauschsystem (SDI). Die Software erstellt die FatturaPA-XML-Datei und sendet sie an die konfigurierte URL.',
  'impostazioni.sdi.comeFunziona': 'Wie der Versand funktioniert',
  'impostazioni.sdi.guidaP1': 'Ein direkt beim Austauschsystem akkreditierter Kanal zu werden, erfordert technische und gesellschaftsrechtliche Voraussetzungen, die ein persönliches/Open-Source-Projekt nicht hat. Der realistische Weg ist, sich auf einen bereits akkreditierten Vermittler zu stützen, der Versand und Empfang per API anbietet (Aruba, Fatture in Cloud oder ein anderer Anbieter Ihrer Wahl).',
  'impostazioni.sdi.guidaStep1': 'Prüfen Sie in Ihrem Konto beim Vermittler, ob der Tarif den API-Zugang enthält (nicht nur das Webportal), und holen Sie Endpunkt und Schlüssel aus dem Entwickler-/API-Bereich der Website.',
  'impostazioni.sdi.guidaStep2': 'Wählen Sie unten den Anbieter: Bei Aruba und Fatture in Cloud wird die URL automatisch ausgefüllt; bei „Anderer Vermittler" geben Sie den vom Anbieter bereitgestellten Endpunkt ein.',
  'impostazioni.sdi.guidaStep3': 'Fügen Sie den API-Schlüssel ein und speichern Sie: Ab diesem Zeitpunkt verwendet „An SDI senden" bei Rechnungen diese Konfiguration.',
  'impostazioni.sdi.guidaFallback': 'Ohne hier etwas zu konfigurieren, bleibt jede Rechnung als gültige FatturaPA-XML herunterladbar (Menü ⋮ auf der Rechnung → „FatturaPA-XML herunterladen"): Sie können sie selbst im Portal Ihres Vermittlers hochladen oder kostenlos bei „Fatture e Corrispettivi" der italienischen Finanzbehörde.',
  'impostazioni.sdi.provider': 'Anbieter',
  'impostazioni.sdi.altroIntermediario': 'Anderer Vermittler (URL + Schlüssel)',
  'impostazioni.sdi.ficNote': 'Die vollständige automatische Integration mit Fatture in Cloud (Login und Senden/Empfangen mit einem Klick) kommt bald. Vorerst können Sie den generischen Versand nutzen, indem Sie den API-Endpunkt und den Schlüssel Ihres Kontos eingeben.',
  'impostazioni.sdi.urlApi': 'SDI-API-URL',
  'impostazioni.sdi.apiKey': 'API-Schlüssel',
