  'impostazioni.dati.doveTitle': 'Wo sich Ihre Daten befinden',
  'impostazioni.dati.doveHint': 'Die gesamte Software befindet sich in einem Ordner auf Ihrem Computer. Sie können ihn öffnen, beliebig verschieben (auch in Dropbox, OneDrive oder iCloud) und von einem anderen Computer aus verwenden.',
