  'impostazioni.dati.avviaAllAccensione': 'Ordeva beim Hochfahren des Computers starten',
  'impostazioni.dati.avviaAllAccensioneHint': 'Beim Systemstart startet Ordeva von selbst und bleibt im Benachrichtigungsbereich (Tray). Beim Schließen des Fensters bleibt es dort: Um wirklich zu beenden, verwenden Sie „Sicher schließen" oder das Tray-Menü.',
  'impostazioni.dati.cronologiaTitle': 'Versionsverlauf (Snapshots)',
  'impostazioni.dati.cronologiaHint': 'Ordeva speichert selbstständig „Wiederherstellungspunkte" Ihrer Daten (alle paar Stunden). Von hier aus können Sie spontan einen erstellen oder zu einem früheren zurückkehren. Vor der Wiederherstellung wird ohnehin eine Sicherheitskopie des aktuellen Zustands gespeichert.',
  'impostazioni.dati.creaSnapshotOra': 'Snapshot jetzt erstellen',
  'impostazioni.dati.colDataOra': 'Datum und Uhrzeit',
  'impostazioni.dati.nessunoSnapshot': 'Noch keine Snapshots. In Kürze wird automatisch einer erstellt.',
  'impostazioni.dati.cifraturaTitle': 'Verschlüsselung und Passwort',
  'impostazioni.dati.cifraturaHint': 'Der Passwortschutz erfolgt jetzt pro Archiv: Jedes Archiv wird mit seinem eigenen Passwort verschlüsselt (beim Öffnen erforderlich), und seine Backups sind nur damit lesbar. Legen Sie das Passwort im Bildschirm Archive fest oder entfernen Sie es (Eintrag im linken Menü).',
  'impostazioni.dati.multiComputerTitle': 'Nutzung auf mehreren Computern (Dropbox)',
  'impostazioni.dati.multiComputerHint': 'Wenn Sie den Datenordner in Dropbox aufbewahren, können Sie Ordeva auch von einem anderen Computer aus nutzen, jeweils einem. Wenn Sie fertig sind, verwenden Sie „Sicher schließen": Ordeva konsolidiert die Daten in einer einzigen Datei, damit Dropbox sie synchronisiert, bevor Sie die App anderswo öffnen. Das gleichzeitige Öffnen auf zwei Computern kann die Daten beschädigen.',
