  'aiuto.quickStart.title': 'In 5 Minuten loslegen',
  'aiuto.quickStart.card1.titolo': 'Unternehmen einrichten',
  'aiuto.quickStart.card1.desc': 'Firmenname, USt-IdNr., Adresse, Logo eingeben',
  'aiuto.quickStart.card2.titolo': 'Kunden hinzufügen',
