  'welcome.choice.title': 'Willkommen bei Ordeva',
  'welcome.choice.sub': 'Ihre Unternehmenssoftware ist bereit. Wählen Sie zum Start eine Option.',
  'welcome.choice.azienda.h': 'Mein Unternehmen eingeben',
  'welcome.choice.azienda.t': 'Firmenname, USt-IdNr. und Adresse: erscheinen auf Rechnungen und Dokumenten.',
  'welcome.choice.demo.h': 'Mit Demodaten ausprobieren',
