  'glossario.piva.titolo': 'USt-IdNr.',
  'glossario.piva.descrizione': 'Eine 11-stellige Nummer, die ein Unternehmen oder einen Freiberufler steuerlich identifiziert.',
  'glossario.piva.esempio': '01234567890',
  'glossario.codiceFiscale.titolo': 'Steuernummer',
  'glossario.codiceFiscale.descrizione': 'Identifiziert eine Person (16 Zeichen) oder ein Unternehmen (11 Ziffern, oft identisch mit der USt-IdNr.).',
  'glossario.codiceFiscale.esempio': 'RSSMRA80A01H501U',
  'glossario.sdi.titolo': 'SDI-Code (Empfängercode)',
  'glossario.sdi.descrizione': 'Ein 7-stelliger Code, über den die italienische Steuerbehörde elektronische Rechnungen zustellt. Hat der Kunde keinen, leer lassen und stattdessen die PEC-Adresse verwenden.',
  'glossario.sdi.esempio': 'ABC1234',
  'glossario.pec.titolo': 'PEC (zertifizierte E-Mail)',
  'glossario.pec.descrizione': 'Eine rechtsverbindliche E-Mail-Adresse. Wird zur Zustellung elektronischer Rechnungen verwendet, wenn der SDI-Code fehlt.',
  'glossario.pec.esempio': 'firma@pec.it',
  'glossario.tipoSoggetto.titolo': 'Kundentyp',
  'glossario.tipoSoggetto.descrizione': 'Gibt an, ob der Kunde eine Privatperson/ein Unternehmen, ein Freiberufler oder eine öffentliche Verwaltung ist. Ändert die für die elektronische Rechnung erforderlichen Daten.',
  'glossario.cig.titolo': 'CIG (Ausschreibungskennung)',
  'glossario.cig.descrizione': 'Ein auf Rechnungen an öffentliche Verwaltungen erforderlicher Code, der an eine Ausschreibung gebunden ist.',
  'glossario.cig.esempio': 'Z123456789',
  'glossario.cup.titolo': 'CUP (eindeutiger Projektcode)',
  'glossario.cup.descrizione': 'Ein Code, der ein öffentliches Investitionsprojekt identifiziert. Auf manchen Rechnungen an öffentliche Verwaltungen erforderlich.',
  'glossario.cup.esempio': 'C57I18000050006',
  'glossario.aliquotaIva.titolo': 'Mehrwertsteuersatz',
  'glossario.aliquotaIva.descrizione': 'Der angewendete Mehrwertsteuersatz. In Italien normalerweise 22 %, mit ermäßigten (10 %, 5 %, 4 %) oder befreiten Fällen.',
  'glossario.aliquotaIva.esempio': '22 %',
  'glossario.ritenuta.titolo': 'Quellensteuer',
  'glossario.ritenuta.descrizione': 'Der Anteil, den der Kunde vom Honorar des Freiberuflers einbehält und in dessen Namen an den Staat abführt (in der Regel 20 %).',
  'glossario.iban.titolo': 'IBAN',
  'glossario.iban.descrizione': 'Die Bankverbindung, auf der Zahlungen empfangen werden. In Italien hat sie 27 Zeichen.',
  'glossario.iban.esempio': 'IT60X0542811101000000123456',
  'glossario.splitPayment.titolo': 'Split Payment',
  'glossario.splitPayment.descrizione': 'Bei Rechnungen an öffentliche Verwaltungen: Die Mehrwertsteuer wird direkt von der Behörde abgeführt, nicht von Ihnen.',
  'glossario.reverseCharge.titolo': 'Reverse Charge (Steuerschuldumkehr)',
  'glossario.reverseCharge.descrizione': 'In manchen Branchen wird die Mehrwertsteuer vom Kunden statt vom Lieferanten entrichtet. Die Rechnung muss ohne Mehrwertsteuer ausgestellt werden.',
  'glossario.esterometro.titolo': 'Esterometro (grenzüberschreitende Meldung)',
  'glossario.esterometro.descrizione': 'Meldung von Geschäften mit ausländischen Kunden/Lieferanten an die italienische Steuerbehörde.',
  'glossario.lipe.titolo': 'LIPE (periodische Mehrwertsteuerabrechnung)',
  'glossario.lipe.descrizione': 'Vierteljährliche Meldung der berechneten Mehrwertsteuerschuld oder -guthaben.',
  'glossario.ddt.titolo': 'Lieferschein (DDT)',
  'glossario.ddt.descrizione': 'Begleitet die Ware während des Transports. Daraus lässt sich anschließend die Rechnung erstellen.',
  'glossario.listino.titolo': 'Preisliste',
  'glossario.listino.descrizione': 'Eine Reihe individueller Preise, die einem Kunden anstelle der Grundpreise zugewiesen werden.',
  'shortcutsDialog.title': 'Tastenkombinationen',
  'shortcutsDialog.ricercaRapida': 'Schnellsuche und Befehle',
  'shortcutsDialog.nuovoElemento': 'Neues Element (wo verfügbar)',
  'shortcutsDialog.apriModifica': 'Zeile öffnen/bearbeiten',
  'shortcutsDialog.doppioClic': 'Doppelklick',
  'shortcutsDialog.mostraScorciatoie': 'Diese Tastenkombinationen anzeigen',
  'shortcutsDialog.chiudiRicerca': 'Suche oder Fenster schließen',
  'shortcutsDialog.notePart1': 'Drücken Sie jederzeit',
  'shortcutsDialog.notePart2': ', um diese Liste erneut zu öffnen.',
