  // ── Autofatture per acquisti dall’estero (reverse charge) ──
  'nav.autofatture': 'Auslandsgutschriften',
  'aiuto.sez.autofatture.titolo': 'Eigenrechnungen für Auslandseinkäufe',
  'aiuto.sez.autofatture.intro': 'Beim Einkauf bei einem ausländischen Lieferanten stellt dieser keine Umsatzsteuer in Rechnung: Sie müssen sie selbst berechnen und abführen, mit einem elektronischen Beleg, der auf Sie selbst lautet. Ordeva bereitet ihn aus der Originalrechnung vor und lässt Sie vor dem Ausstellen alles prüfen.',
  'aiuto.sez.autofatture.passo0.titolo': 'Beginnen Sie mit der Auslandsrechnung',
  'aiuto.sez.autofatture.passo0.descrizione': 'Unter Einkauf → Auslandsgutschriften auf „Auslandsrechnung scannen“ klicken und das PDF (oder Foto) des Lieferanten wählen. Das Programm übernimmt die Zeilen unverändert und legt einen Entwurf an. Das Dokument verlässt Ihren Rechner nicht.',
  'aiuto.sez.autofatture.passo1.titolo': 'Prüfen Sie die Belegart',
  'aiuto.sez.autofatture.passo1.descrizione': 'TD17 für Dienstleistungen aus dem Ausland, TD18 für Waren aus einem anderen EU-Land, die nach Italien gelangt sind, TD19 für Waren eines ausländischen Lieferanten, die bereits in Italien waren. Das Programm schlägt anhand von Land und Zeilen eine Art vor, die Entscheidung bleibt bei Ihnen: Bei Waren aus Drittländern wird die Steuer in der Regel beim Zoll entrichtet, dann braucht es keine Eigenrechnung.',
  'aiuto.sez.autofatture.passo2.titolo': 'Italienischen Steuersatz und ggf. den Wechselkurs eintragen',
  'aiuto.sez.autofatture.passo2.descrizione': 'Auf der Auslandsrechnung steht keine Steuer: In jeder Zeile tragen Sie den italienischen Satz ein, der gegolten hätte. Lautet die Rechnung auf eine Fremdwährung, wählen Sie Währung und Kurs des Geschäftstags: Die Eurobeträge werden neu berechnet, die Originalbeträge bleiben zum Vergleich sichtbar.',
  'aiuto.sez.autofatture.passo3.titolo': 'Prüfungen bestehen und bestätigen',
  'aiuto.sez.autofatture.passo3.descrizione': 'Am Seitenende listet das Programm auf, was nicht stimmt (Zeilen, die nicht zur Summe passen, fehlende Nummer der Auslandsrechnung, verstrichene Frist) und welche Punkte Sie mit Blick auf den Beleg abhaken müssen. Solange ein Haken fehlt, bleibt „Bestätigen und ausstellen“ inaktiv. Mit der Bestätigung entsteht auch der verknüpfte Einkauf, denn der Beleg gehört sowohl ins Verkaufs- als auch ins Einkaufsbuch; von dort laden Sie die XML-Datei herunter, in der Regel bis zum 15. des Folgemonats.',
  'autofatture.titolo': 'Eigenrechnungen für Auslandseinkäufe',
  'autofatture.sottotitolo': 'Beim Einkauf bei einem ausländischen Lieferanten schulden Sie die Umsatzsteuer selbst: Hier entsteht das Dokument aus der Originalrechnung und wird Zeile für Zeile geprüft.',
  'autofatture.nuova': 'Neue Eigenrechnung',
  'autofatture.scansiona': 'Auslandsrechnung scannen',
  'autofatture.scansionaRighe': 'Dokument erneut lesen und Zeilen übernehmen',
  'autofatture.nessuna': 'Keine Eigenrechnungen',
  'autofatture.nessunaSub': 'Beginnen Sie mit der Auslandsrechnung: Das Programm übernimmt ihre Zeilen und bereitet das Dokument zur Prüfung vor.',
  'autofatture.lettura': 'Die Auslandsrechnung wird gelesen…',
  'autofatture.letturaSub': 'Das Dokument bleibt auf Ihrem Rechner: Es wird nirgendwohin gesendet.',
  'autofatture.letturaOcr': 'Die Rechnung ist ein Scan: Das Lesen dauert einige Sekunden länger.',
  'autofatture.indietro': 'Zurück',
  'autofatture.salva': 'Speichern',
  'autofatture.confermaEmetti': 'Bestätigen und ausstellen',
  'autofatture.scaricaXml': 'XML herunterladen',
  'autofatture.riapri': 'Als Entwurf öffnen',
  'autofatture.giaConfermata': 'Eigenrechnung bestätigt: Zum Ändern als Entwurf wieder öffnen. Der verknüpfte Einkauf wird bei der nächsten Bestätigung neu erstellt.',
  'autofatture.scegliFornitore': '— ausländischen Lieferanten wählen —',
  'autofatture.righe': 'Aus der Auslandsrechnung übernommene Zeilen',
  'autofatture.righeSpiega': 'Die Zeilen müssen dem Original genau entsprechen. Das Einzige, was Sie ergänzen, ist der anzuwendende italienische Steuersatz: Auf der Auslandsrechnung steht er nicht.',
  'autofatture.aggiungiRiga': 'Zeile hinzufügen',
  'autofatture.verifiche': 'Prüfungen vor dem Ausstellen',
  'autofatture.verificheSpiega': 'Das Programm prüft, was es prüfen kann; den Rest vergleichen Sie mit der Rechnung, die vor Ihnen liegt. Solange ein Haken fehlt, lässt sich das Dokument nicht bestätigen.',
  'autofatture.salvaPerVerificare': 'Speichern Sie den Entwurf, um die Prüfungen zu starten.',
  'autofatture.nessunProblema': 'Die automatischen Prüfungen haben nichts beanstandet.',
